@pytest.mark.parametrize("scenario,profile", E2E.TESTS) def test_local_renderer_matches_java_and_scalar(scenario, profile): binary = Path(os.environ["LMYZMAIL_LOCAL_RENDER_BINARY"]).resolve(strict=True) capabilities_path = Path(os.environ["LMYZMAIL_LOCAL_RENDER_CAPABILITIES"]) capabilities = json.loads(capabilities_path.read_text())["host_capabilities"] assert capabilities["avx2"] and capabilities["fma"] output = Path(os.environ["LMYZMAIL_LOCAL_RENDER_OUTPUT"]) / f"{scenario}.json" assert not output.exists() head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=ROOT, text=True).strip() assert not subprocess.check_output(["git", "diff", "HEAD", "--", "crates", "Cargo.lock", ".cargo"], cwd=ROOT) source_digest = E2E.sha256_bytes(head.encode() + (ROOT / "Cargo.lock").read_bytes()) mail_view, video, runner, scenario_type, candidate_runtime, runtime_module = E2E._load_blackbox() module = video if scenario == "minecraft-video" else mail_view original = module.SCENARIOS[0] observations = {} runs = [] with contextlib.ExitStack() as resources: binary_pin = E2E.RENDERER_VERIFIER.PinnedFile(binary, label="local candidate", executable=True) resources.callback(binary_pin.close) for mode, backend in (("SCALAR", "scalar"), ("AVX2", "avx2+fma")): captured = {}
def capture(target): captured["observation"] = original.capture(target) return captured["observation"]
wrapped = scenario_type(original.name, capture, normalizers=original.normalizers, contract=original.contract) observer = E2E.ObserverPipe() session = secrets.token_hex(32) runtime = E2E._candidate_runtime( scenario, binary_pin, mode, candidate_runtime, observer, source_sha256=source_digest, session=session, ) lock = mail_view._renderer_capture_lock() if scenario == "minecraft-mail-view" else contextlib.nullcontext() try: with E2E.candidate_process_with_fds(runtime_module, observer, binary_pin.descriptor): with E2E.scenario_deadline(1800), lock, runtime as candidate: > runner(ROOT, ROOT / "blackbox/golden/java" / profile, profile).verify_candidate((wrapped,), candidate)
